UPDATE market_autogen SET enabled = 1, checked_by = #{checkedBy}, checked_at = #{now}, checked_template_version = #{templateVersion},
  version = version + 1, updated_by = #{checkedBy}, updated_at = #{now}
WHERE id = #{id} AND enabled = 0

UPDATE market_template SET name = #{name}, title_en = #{titleEn}, title_zh_cn = #{titleZhCn}, title_zh_tw = #{titleZhTw}, rules_en = #{rulesEn},
  rules_zh_cn = #{rulesZhCn}, rules_zh_tw = #{rulesZhTw}, source_primary = #{sourcePrimary}, source_backup = #{sourceBackup}, options = #{options},
  version = version + 1, updated_by = #{updatedBy}, updated_at = #{updatedAt}
WHERE id = #{id}
